export function sumMonthsOverEarners(
  op: OnboardingProfile | null, of: (w: EarnerWage) => number[],
): number[]

export function salaryCalendarYear(
  op: OnboardingProfile | null, year: number, fallback = 0, now: Date = new Date(),
): number[]

export function salaryWindow(
  op: OnboardingProfile | null, keys: string[], fallback = 0, now: Date = new Date(),
): [string, number][]

export function withSalaryMonth(
  op: OnboardingProfile | null, key: string, amount: any, now: Date = new Date(),
): Record<string, number>

export function extraIncome(op: OnboardingProfile | null): {
  taxableMonthly: number; nontaxMonthly: number; onetimeTaxable: number; onetimeNontax: number;
  reinvestedMonthly: number;
}

export function incomeFromAccounts(
  accounts: AssetAccount[] | null | undefined,
  transactions?: any[] | null,
  now: Date = new Date(),
): AccountIncome

export function debtPaymentsCountedAsExpenses(
  s: ExpensesInput, purchasesCaptured: Set<string> = new Set(),
): { label: string; amount: number }[]

export function annualCashflow(op: OnboardingProfile | null): {
  grossYr: number; taxYr: number; netYr: number; k401Yr: number; availableYr: number; spendYr: number; saveYr: number;
}

export function whatsComing(input: {
  profile: any;
  startBalance?: number;
  now?: Date;
  horizonDays?: number;
  /** every debt: its payments come out of the table's months, so out of what is there by a bill's day too (DEC-0269) */
  debts?: any[];
  /** the month table the screen draws. Handed in, the bills read it, so the COMING UP line and the End column cannot disagree
   *  (2026-10-24, E2E-81); without one, it is built here by the same function from the budget, the debts and the balance. */
  grid?: DatedGrid;
}): WhatsComing

export function upcomingBills(
  op: OnboardingProfile | null,
  grid: DatedGrid,
  now: Date = new Date(),
  opts: { bufferDays?: number; askLeadDays?: number; horizonDays?: number } = {},
): UpcomingBill[]

export function theDebts(input: { debts: Debt[]; extraMonthly?: number; method?: PayoffMethod; now?: Date;
  /** what every debt together stood at on the earliest month-end recorded this year, if any */
  startOfYearDebt?: number | null }): TheDebts

export function mortgageOddsEffect(args: {
  base: RetirementInputs;
  balance: number;
  annualRate: number;
  monthlyPayment: number;
  extraMonthly: number;
  nowYear: number;
}): MortgageOddsEffect | null

export function compareMortgageToTreasury(args: {
  balance: number;
  annualRate: number;          // decimal, e.g. 0.055
  monthlyPayment: number;
  extraMonthly: number;
  treasuryYield: number;       // decimal, e.g. 0.0463
}): MortgageComparison | null

export function theContributionRoom(input: {
  profile: any;
  /** THE DAY IT IS READ ON. Absent means today, which is what the app passes. A worked example passes
   *  a fixed day, because "how much is left to put in this year" depends on the month — and an example
   *  whose answer changes when the calendar turns is an example that cannot be checked. This one broke
   *  on 2026-10-01 for exactly that reason: it said $5,300/month in September and $7,100 in October. */
  today?: Date;
}): ContributionRoom

export function futurePaycheck(input: {
  op: any; accounts: any[]; assumptions: any; bigCosts?: any[]; inflationRate?: number; employmentStatus?: any;
}): FuturePaycheck | null

export function pastMonthFlow(
  snap: { income_net?: number | null; spending?: number | null; debt_paid?: number | null } | null | undefined,
  incomes: { amount?: unknown; date?: unknown }[] | null | undefined, expenses: LoggedExpense[] | null | undefined, ym: string,
): { inflow: number; outflow: number; surplus: number }

export function addedAfterRecord(
  snap: { captured_at?: string | null } | null | undefined,
  expenses: (LoggedExpense & { id?: string; createdAt?: string })[] | null | undefined, ym: string,
): { ids: Set<string>; total: number }

export function theTaxOrganizer(input: {
  profile: any;
  accounts: any[];
  debts: any[];
  transactions: any[];
  year?: number;
}): TaxOrganizer
